import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction, BaseInterfaceErrors } from '@bk-dash/core-typescript'
import { CampaignProductBindingRepository } from '../repositories/CampaignProductBindingRepository'
import { CampaignProductBindingCreatedEvent } from '../events'

export const BindCampaignToProductInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	campaignId: z.uuid(),
	productIds: z.array(z.uuid()).default([]),
	variantIds: z.array(z.uuid()).default([]),
})

export const BindCampaignToProductOutputSchema = z.void()

/**
 * C36 BindCampaignToProduct. Creates one row per (campaignId, productId)
 * and one per (campaignId, variantId). Idempotent at the row level —
 * Mock + Drizzle dedupe via the unique index on
 * `(campaignId, productId, variantId)` with ON CONFLICT DO NOTHING.
 *
 * Emits CampaignProductBindingCreatedEvent with the input lists so the
 * cross-BC bridge handler can publish the
 * `integration.shared.marketing.campaign_product_binding_created`
 * integration event for Analytics ROAS recompute.
 *
 * VALIDATION_ERROR when both productIds and variantIds are empty — the
 * call would be a no-op and no event should fire.
 */
@injectable()
export class BindCampaignToProduct extends Handler<typeof BindCampaignToProductInputSchema, typeof BindCampaignToProductOutputSchema> {
	readonly name = 'bind_campaign_to_product' as const
	readonly inputSchema = BindCampaignToProductInputSchema
	readonly outputSchema = BindCampaignToProductOutputSchema

	constructor(private readonly bindings: CampaignProductBindingRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		if (input.productIds.length === 0 && input.variantIds.length === 0) {
			throw new BaseError<BaseInterfaceErrors>('VALIDATION_ERROR', 'productIds or variantIds must be non-empty')
		}

		await this.withTransaction(tx, async tx => {
			const rows = [
				...input.productIds.map(productId => ({
					id: crypto.randomUUID(),
					storeId: input.storeId,
					campaignId: input.campaignId,
					productId,
					variantId: null,
				})),
				...input.variantIds.map(variantId => ({
					id: crypto.randomUUID(),
					storeId: input.storeId,
					campaignId: input.campaignId,
					productId: null,
					variantId,
				})),
			]

			await this.bindings.bindMany(rows, tx)

			await this.domainEventRepository.save(
				new CampaignProductBindingCreatedEvent({
					entityId: input.campaignId,
					ownerId: input.storeId,
					payload: {
						storeId: input.storeId,
						campaignId: input.campaignId,
						productIds: input.productIds,
						variantIds: input.variantIds,
					},
				}),
				tx,
			)
		})

		return
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CredentialVault } from '@bk-dash/core-typescript'
import { SalesPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'
import { TriggerReintegration } from './TriggerReintegration'
import { StoreIntegration } from '../entities/StoreIntegration'
import { IntegrationCredentialSecret } from '../entities/IntegrationCredentialSecret'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../repositories/IntegrationCredentialSecretRepository'

const STORE_ID = testId('store', '1')
const USER = testId('user', '1')

/**
 * SPEC-17: TriggerReintegration now calls the Go worker through the generated
 * SDK `Client` singleton (stubbed to a 204 in mock/integration mode), not the
 * deleted hand-written GoSyncWorkerClient. jobId is synthesized locally since
 * the SDK's /sync returns No Content.
 */
describe('TriggerReintegration use case (C23)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: TriggerReintegration
	let storeIntegrationRepo: StoreIntegrationRepository
	let credentialSecretRepo: IntegrationCredentialSecretRepository
	let vault: CredentialVault

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(TriggerReintegration)
		storeIntegrationRepo = testBed.resolve(StoreIntegrationRepository)
		credentialSecretRepo = testBed.resolve(IntegrationCredentialSecretRepository)
		vault = testBed.resolve(CredentialVault)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedActiveIntegrationWithSecret(): Promise<StoreIntegration> {
		const i = StoreIntegration.create({
			storeId: STORE_ID,
			platform: { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY },
			externalId: 'acme.myshopify.com',
			displayName: 'Acme Store',
			ownerId: USER,
		})
		const sealed = await vault.seal({
			shopDomain: 'acme.myshopify.com',
			accessToken: 'shpat_xyz',
		})
		const secret = IntegrationCredentialSecret.create({
			storeIntegrationId: i.id.value,
			sealed,
		})
		i.attachCredentialSecret(secret.id.value)
		await storeIntegrationRepo.save(i)
		await credentialSecretRepo.save(secret)
		return i
	}

	it('happy path: opens creds, calls Go sync via SDK, returns synthesized jobId + ETA', async () => {
		const integration = await seedActiveIntegrationWithSecret()

		const result = await useCase.execute({
			userId: USER,
			storeId: STORE_ID,
			storeIntegrationId: integration.id.value,
		})

		expect(typeof result.jobId).toBe('string')
		expect(result.jobId.length).toBeGreaterThan(0)
		expect(result.estimatedCompletionAt).toBeInstanceOf(Date)
	})

	it('inactive integration → STORE_INTEGRATION_INACTIVE', async () => {
		const i = StoreIntegration.create({
			storeId: STORE_ID,
			platform: { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY },
			externalId: 'acme.myshopify.com',
			displayName: 'Acme Store',
			ownerId: USER,
		})
		i.toggleActive(false) // born active on create; deactivate to exercise the guard
		await storeIntegrationRepo.save(i)

		await expect(useCase.execute({ userId: USER, storeId: STORE_ID, storeIntegrationId: i.id.value })).rejects.toMatchObject({
			name: 'STORE_INTEGRATION_INACTIVE',
		})
	})

	it('unknown integration id → STORE_INTEGRATION_NOT_FOUND', async () => {
		await expect(useCase.execute({ userId: USER, storeId: STORE_ID, storeIntegrationId: crypto.randomUUID() })).rejects.toMatchObject({
			name: 'STORE_INTEGRATION_NOT_FOUND',
		})
	})

	it('integration from another store → STORE_INTEGRATION_NOT_FOUND (tenant scope)', async () => {
		const integration = await seedActiveIntegrationWithSecret()

		await expect(
			useCase.execute({ userId: USER, storeId: testId('store', '2'), storeIntegrationId: integration.id.value }),
		).rejects.toMatchObject({ name: 'STORE_INTEGRATION_NOT_FOUND' })
	})

	it('missing credential secret → STORE_INTEGRATION_CREDENTIAL_NOT_FOUND', async () => {
		const i = StoreIntegration.create({
			storeId: STORE_ID,
			platform: { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY },
			externalId: 'acme.myshopify.com',
			displayName: 'Acme Store',
			ownerId: USER,
		})
		await storeIntegrationRepo.save(i)

		await expect(useCase.execute({ userId: USER, storeId: STORE_ID, storeIntegrationId: i.id.value })).rejects.toMatchObject({
			name: 'STORE_INTEGRATION_CREDENTIAL_NOT_FOUND',
		})
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DrizzleClient } from '@bk-dash/core-typescript'
import { pixelEvents } from '@bk-dash/contracts/db'
import { PixelEventType } from '@bk-dash/contracts-typescript/wire/enums'
import { PixelEventReadRepository } from './PixelEventReadRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')
const INTEG_A1 = testId('integration', 'a1')
const INTEG_A2 = testId('integration', 'a2')

describe('DrizzlePixelEventReadRepository (integration)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: PixelEventReadRepository
	let db: any

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(PixelEventReadRepository)
		db = testBed.resolve(DrizzleClient) as any
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seed(opts: {
		storeId: string
		storeIntegrationId: string
		eventType: PixelEventType
		visitorKey: string
		externalEventId: string
		occurredAt: Date
	}): Promise<void> {
		await db.insert(pixelEvents).values({
			id: crypto.randomUUID(),
			storeId: opts.storeId,
			storeIntegrationId: opts.storeIntegrationId,
			storeIntegrationExternalId: 'shop.myshopify.com',
			platform: 'SHOPIFY',
			externalEventId: opts.externalEventId,
			eventType: opts.eventType,
			visitorKey: opts.visitorKey,
			occurredAt: opts.occurredAt,
			receivedAt: new Date(),
		})
	}

	it('returns empty array when no events match', async () => {
		const stages = await repo.aggregateFunnelStages({
			storeIds: [STORE_A],
			from: new Date('2026-05-01T00:00:00.000Z'),
			to: new Date('2026-05-31T23:59:59.999Z'),
		})
		expect(stages).toEqual([])
	})

	it('groups events by type + counts distinct visitor sessions', async () => {
		// 3 page views from 2 visitors
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v1',
			externalEventId: 'e1',
			occurredAt: new Date('2026-05-22T10:00:00Z'),
		})
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v1',
			externalEventId: 'e2',
			occurredAt: new Date('2026-05-22T10:01:00Z'),
		})
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v2',
			externalEventId: 'e3',
			occurredAt: new Date('2026-05-22T10:02:00Z'),
		})

		const stages = await repo.aggregateFunnelStages({
			storeIds: [STORE_A],
			from: new Date('2026-05-01T00:00:00.000Z'),
			to: new Date('2026-05-31T23:59:59.999Z'),
		})
		const pageView = stages.find(s => s.type === PixelEventType.PAGE_VIEWED)
		expect(pageView?.count).toBe(3)
		expect(pageView?.uniqueSessions).toBe(2)
	})

	it('filters by storeIntegrationIds when supplied', async () => {
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v1',
			externalEventId: 'e1',
			occurredAt: new Date('2026-05-22T10:00:00Z'),
		})
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A2,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v2',
			externalEventId: 'e2',
			occurredAt: new Date('2026-05-22T10:00:00Z'),
		})

		const filtered = await repo.aggregateFunnelStages({
			storeIds: [STORE_A],
			storeIntegrationIds: [INTEG_A1],
			from: new Date('2026-05-01T00:00:00.000Z'),
			to: new Date('2026-05-31T23:59:59.999Z'),
		})
		expect(filtered.find(s => s.type === PixelEventType.PAGE_VIEWED)?.count).toBe(1)
	})

	it('filters by date range', async () => {
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v1',
			externalEventId: 'e1',
			occurredAt: new Date('2026-04-15T10:00:00Z'),
		})
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v2',
			externalEventId: 'e2',
			occurredAt: new Date('2026-05-22T10:00:00Z'),
		})

		const may = await repo.aggregateFunnelStages({
			storeIds: [STORE_A],
			from: new Date('2026-05-01T00:00:00.000Z'),
			to: new Date('2026-05-31T23:59:59.999Z'),
		})
		expect(may.find(s => s.type === PixelEventType.PAGE_VIEWED)?.count).toBe(1)
	})

	it('isolates by storeIds (cross-store leak protection)', async () => {
		await seed({
			storeId: STORE_A,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v1',
			externalEventId: 'e1',
			occurredAt: new Date('2026-05-22T10:00:00Z'),
		})
		await seed({
			storeId: STORE_B,
			storeIntegrationId: INTEG_A1,
			eventType: PixelEventType.PAGE_VIEWED,
			visitorKey: 'v2',
			externalEventId: 'e2',
			occurredAt: new Date('2026-05-22T10:00:00Z'),
		})

		const storeA = await repo.aggregateFunnelStages({
			storeIds: [STORE_A],
			from: new Date('2026-05-01T00:00:00.000Z'),
			to: new Date('2026-05-31T23:59:59.999Z'),
		})
		expect(storeA.find(s => s.type === PixelEventType.PAGE_VIEWED)?.count).toBe(1)
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId, givenStoreIntegration } from '@test/support'
import { SalesPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'
import { GetPixelScriptSnippet } from './GetPixelScriptSnippet'

const STORE = testId('store', '1')
const OWNER = 'user-owner-1'

describe('GetPixelScriptSnippet use case (T24)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: GetPixelScriptSnippet

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(GetPixelScriptSnippet)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('returns Shopify snippet with the correct embedded storeIntegrationId', async () => {
		const integration = await givenStoreIntegration(testBed, {
			storeId: STORE,
			ownerId: OWNER,
			platform: { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.SHOPIFY },
			externalId: 'foo.myshopify.com',
			displayName: 'Foo Store',
		})

		const result = await useCase.execute({ storeId: STORE })

		expect(result.storeIntegrationId).toBe(integration.id.value)
		expect(result.platform).toBe(SalesPlatform.SHOPIFY)
		expect(result.scriptUrl).toContain('bkdash-pixel.js')
		expect(result.inlineScript).toContain(integration.id.value)
		expect(result.installationInstructions).toContain('theme.liquid')
	})

	it('throws STORE_INTEGRATION_NOT_FOUND when the store has no sales-channel integration', async () => {
		await expect(useCase.execute({ storeId: crypto.randomUUID() })).rejects.toMatchObject({
			name: 'STORE_INTEGRATION_NOT_FOUND',
		})
	})

	it('throws PIXEL_NOT_SUPPORTED_FOR_PLATFORM for non-Shopify integrations', async () => {
		await givenStoreIntegration(testBed, {
			storeId: STORE,
			ownerId: OWNER,
			platform: { type: StoreIntegrationType.SALES_CHANNEL, platform: SalesPlatform.NUVEM_SHOP },
			externalId: 'foo.myshopify.com',
			displayName: 'Foo Store',
		})

		await expect(useCase.execute({ storeId: STORE })).rejects.toMatchObject({
			name: 'PIXEL_NOT_SUPPORTED_FOR_PLATFORM',
		})
	})
})
